import math

def solve():
    intervals = []
    for k in range(1, 1000):
        l_k = k**(1/k)
        r_k = (k+1)**(1/k)
        intervals.append((l_k, r_k, k))

    pts = []
    for l, r, k in intervals:
        pts.append(l)
        pts.append(r)
    pts = sorted(list(set(pts)))

    max_o = 0
    best_p = 0
    for p in pts:
        count = 0
        for l, r, k in intervals:
            if l <= p < r:
                count += 1
        if count > max_o:
            max_o = count
            best_p = p

    # Now find the ks for this best_p
    best_ks = []
    for l, r, k in intervals:
        if l <= best_p < r:
            best_ks.append(k)

    return max_o, best_p, best_ks

print(solve())

def check_overlap(k):
    l_k = k**(1/k)
    r_k_plus_1 = (k+2)**(1/(k+1))
    return l_k <= r_k_plus_1

for k in range(1, 100):
